// test_battery_temp_range_view.js (M780, spec analyses/M780_spec.md Rev 2): the Thermal-tab section "Battery Temperature - Observed Range" shows one ambient row per observed 5 C bin
// (no fixed cool/mild/hot rows), each with drives, days and the regime tag; the scale comes from the payload; a row with fewer than 5 drives draws no interquartile box and says so;
// a value below 0 C is drawn left of a dashed 0 C line (tested on a copy of the page with a planted negative minimum); the ordering sentence is generated by a strict rule.
const fs = require('fs'); const { JSDOM } = require('jsdom');
if (typeof globalThis.MessageChannel === 'undefined') { globalThis.MessageChannel = class { constructor() { this.port1 = { onmessage: null, postMessage: d => setImmediate(() => this.port2.onmessage && this.port2.onmessage({ data: d })) }; this.port2 = { onmessage: null, postMessage: d => setImmediate(() => this.port1.onmessage && this.port1.onmessage({ data: d })) }; } }; }
const html0 = fs.readFileSync(process.env.XT_HTML || 'xtrail_dashboard.html', 'utf8');
const A = JSON.parse(fs.readFileSync('summary_arrays.json', 'utf8'));
let fails = 0; const ok = (label, c) => { console.log((c ? 'PASS ' : 'FAIL ') + label); if (!c) fails++; };
const rows = A.batteryTempRanges.filter(r => r.group === 'ambient');
const plu = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
async function load(html) {
  const dom = new JSDOM(html, { runScripts: 'dangerously', pretendToBeVisual: true, beforeParse(w) { w.MessageChannel = globalThis.MessageChannel; w.console.error = () => {}; w.console.warn = () => {}; } });
  const d = dom.window.document, sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(1000);
  d.querySelector('button') && [...d.querySelectorAll('button')].find(b => b.textContent.trim().toLowerCase() === 'thermal').dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true }));
  await sleep(600);
  return d;
}
(async () => {
  let d = await load(html0);
  const plots = [...d.querySelectorAll('[data-temp-interval-plot]')]; ok('interval plots present', plots.length >= 2);
  const ambPlot = plots.find(p => p.querySelector('[data-temp-row="' + rows[0].label + '"]')); ok('the ambient panel is present', !!ambPlot); if (!ambPlot) process.exit(1);
  const trs = [...ambPlot.querySelectorAll('[data-temp-row]')];
  ok('one row per observed 5 C ambient bin (' + rows.length + '), coldest first', trs.length === rows.length && trs.every((t, i) => t.getAttribute('data-temp-row') === rows[i].label));
  ok('no fixed cool / mild / hot row remains', !/Cool ambient|Mild ambient|Hot ambient/.test(d.body.textContent));
  rows.forEach((r, i) => { const t = trs[i].textContent;
    ok(r.label + ': drives, days and regime tag equal the payload', t.includes(plu(r.n, 'drive')) && t.includes(plu(r.nDays, 'day')) && t.includes({ cold: 'Cold', shoulder: 'Shoulder', warm: 'Warm' }[r.regime]) && t.includes(r.medPeak + '°C'));
    const few = r.n < 5; ok(r.label + ': ' + (few ? 'fewer than 5 drives: no interquartile box and the label says so' : 'IQR box drawn when the quartiles differ'),
      few ? (!trs[i].querySelector('[data-iqr-box]') && /few drives|single drive/.test(t)) : (r.p75Peak > r.p25Peak ? !!trs[i].querySelector('[data-iqr-box]') : true)); });
  ok('no zero line when no value is below 0 C', !ambPlot.querySelector('[data-zero-line]') || A.batteryTempRanges.some(r => r.lo < 0));
  const sent = d.querySelector('[data-temp-range-note]').textContent;
  ok('the chart note states the exact-5.0 edge rule, the unfiltered extremes and that rows are not cohort counts', /exactly 5\.0/.test(sent) && /not from the canonical-clean set/.test(sent) && /not cohort counts/.test(sent));
  const body = d.body.textContent;
  const R = rows.filter(r => r.n >= 5 && r.nDays >= 3); const up = R.length >= 2 && R.every((r, k) => k === 0 || r.medPeak > R[k - 1].medPeak);
  ok('generated ordering sentence follows the strict rule', up ? /observed median peak is higher in each successive row \(descriptive, no interval\)/.test(body) : /No ordering of the median peak across the ambient rows is stated/.test(body));
  ok('no typed "rises steadily across the three ambient bins" claim', !/three ambient bins/.test(body));
  // planted negative minimum: the scale extends, the 0 C line appears, the value is drawn left of it
  const html1 = html0.replace('"label":"-5 to <0 C","lo":20,', '"label":"-5 to <0 C","lo":-7,');
  ok('the planted copy differs from the page', html1 !== html0);
  d = await load(html1);
  const p1 = [...d.querySelectorAll('[data-temp-interval-plot]')].find(p => p.querySelector('[data-temp-row="-5 to <0 C"]')); ok('planted copy: ambient panel present', !!p1);
  const z = p1 && p1.querySelector('[data-zero-line] line'); ok('planted copy: dashed 0 C line drawn', !!z);
  const row = p1.querySelector('[data-temp-row="-5 to <0 C"]'); const wh = [...row.querySelectorAll('line')][0];
  ok('planted copy: the whisker of the sub-zero minimum starts left of the 0 C line', !!z && !!wh && Number(wh.getAttribute('x1')) < Number(z.getAttribute('x1')));
  const ticks = [...p1.querySelectorAll('text')].map(t => t.textContent);
  ok('planted copy: a negative tick is labelled', ticks.some(t => /^-\d+°$/.test(t)));
  console.log(fails ? 'FAILED ' + fails : 'ALL PASS'); process.exit(fails ? 1 : 0);
})();
